<?php get_header();while(have_posts()):the_post(); ?><article class="article"><p class="eyebrow"><?php echo esc_html(get_the_date()); ?></p><h1><?php the_title(); ?></h1><?php if(has_post_thumbnail())the_post_thumbnail('large'); ?><div><?php the_content(); ?></div></article><?php endwhile;get_footer(); ?>